begin;
create extension if not exists pgtap with schema extensions;
select plan(36);
insert into auth.users(id,email) values('c0000000-0000-4000-8000-000000000001','learning-one@example.test'),('d0000000-0000-4000-8000-000000000001','learning-two@example.test');
select throws_ok($$select start_learning('c0000000-0000-4000-8000-000000000001')$$,'P0001','Complete the initial assessment first','assessment is required');
insert into learning_sessions(user_id,status,starting_state_summary) values('c0000000-0000-4000-8000-000000000001','completed','{"purpose":"initial_assessment_v1"}');
create temp table learning_ids as select start_learning('c0000000-0000-4000-8000-000000000001') sid;
select is(start_learning('c0000000-0000-4000-8000-000000000001'),(select sid from learning_ids),'session start resumes without duplication');
alter table learning_ids add column aid uuid;
update learning_ids set aid=plan_learning('c0000000-0000-4000-8000-000000000001',sid,1,
'{"version":"learning-v1","objective":"Make a polite request","targetSkill":"vocabulary","topic":"polite_requests","purpose":"communication","method":"vocabulary_context","scenario":"daily_life","difficulty":1,"exposure":1,"nativeSupport":4,"correction":"hint_first","support":{"initial":0,"max":6},"collect":["vocabulary"],"triggers":["struggle"],"returnRule":"Return after two tasks","reasons":["goal"]}',
'{"topic":"polite_requests","prompt":"Choose a request","strategy":"exact","answer":"Water, please."}');
select is((select count(*)::int from teaching_decisions where user_id='c0000000-0000-4000-8000-000000000001'),1,'decision stored with activity');
select ok(not claim_learning_response('d0000000-0000-4000-8000-000000000001',(select aid from learning_ids),gen_random_uuid()),'cross-user claim denied');
select ok(claim_learning_response('c0000000-0000-4000-8000-000000000001',(select aid from learning_ids),'c2000000-0000-4000-8000-000000000001'),'response lease acquired');
select ok(not claim_learning_response('c0000000-0000-4000-8000-000000000001',(select aid from learning_ids),gen_random_uuid()),'second worker cannot evaluate concurrently');
select throws_ok(format('select control_learning(%L,%L,%L,%L)','c0000000-0000-4000-8000-000000000001',(select aid from learning_ids),'support','next'),'P0001','Response is processing; retry shortly','support cannot race evaluated answer');
create temp table learning_payload as select jsonb_build_array(jsonb_build_object('id','c3000000-0000-4000-8000-000000000001','activity_id',a.id,'session_id',a.session_id,'knowledge_item_id',a.target_knowledge_item_id,'source','deterministic','evidence_kind','learning_performance','target_skill','vocabulary','modality','reading_recognition','result','success','response_quality',4,'support_level',0,'evaluator_confidence_level',3,'transfer_success',null,'voice_uncertainty',false,'response_time_ms',1000,'dedupe_key',a.id::text||':learning:performance','occurred_at',now(),'metadata','{}'::jsonb)) events,
jsonb_build_array(jsonb_build_object('kind','ability','key','vocabulary','values',jsonb_build_object('dimension','vocabulary','estimate_level',0,'confidence_level',1,'trend','stable','last_evidence_at',now()),'evidence',jsonb_build_array('c3000000-0000-4000-8000-000000000001'))) patches from activities a where id=(select aid from learning_ids);
select ok(not commit_learning_response('c0000000-0000-4000-8000-000000000001',(select aid from learning_ids),'c2000000-0000-4000-8000-000000000001',0,'{"text":"Water, please.","quality":4,"correction":"Your message worked"}',(select events from learning_payload),(select patches from learning_payload),'["c3000000-0000-4000-8000-000000000001"]'),'stale model revision asks server to recompute');
select is((select count(*)::int from evidence_events where user_id='c0000000-0000-4000-8000-000000000001'),0,'stale update writes nothing');
select throws_ok(format('select commit_learning_response(%L,%L,%L,2,%L,%L::jsonb,%L::jsonb,%L::jsonb)',
'c0000000-0000-4000-8000-000000000001',(select aid from learning_ids),'c2000000-0000-4000-8000-000000000001','{"text":"Water"}',(select events::text from learning_payload),(select jsonb_set(patches,'{0,values,estimate_level}','6')::text from learning_payload),'["c3000000-0000-4000-8000-000000000001"]'),'P0001','Ability change too large','invalid derived update aborts transaction');
select is((select count(*)::int from evidence_events where user_id='c0000000-0000-4000-8000-000000000001'),0,'evidence insert rolls back together with failed update');
select ok(commit_learning_response('c0000000-0000-4000-8000-000000000001',(select aid from learning_ids),'c2000000-0000-4000-8000-000000000001',2,'{"text":"Water, please.","quality":4,"correction":"Your message worked"}',(select events from learning_payload),(select patches from learning_payload),'["c3000000-0000-4000-8000-000000000001"]'),'valid evidence/model/message transaction commits');
select is((select processor_status from evidence_events where id='c3000000-0000-4000-8000-000000000001'),'applied','evidence marked applied');
select is((select count(*)::int from learner_model_change_evidence where user_id='c0000000-0000-4000-8000-000000000001'),1,'audit links supporting evidence');
select is((select confidence_level::int from learner_ability_estimates where user_id='c0000000-0000-4000-8000-000000000001'),1,'conservative model update persisted');
select ok(commit_learning_response('c0000000-0000-4000-8000-000000000001',(select aid from learning_ids),'c2000000-0000-4000-8000-000000000001',2,'{}','[]','[]','[]'),'retry of completed response is a no-op');
select is((select count(*)::int from learner_model_changes where user_id='c0000000-0000-4000-8000-000000000001'),1,'retry creates no duplicate model change');
select is((select count(*)::int from activity_messages where user_id='c0000000-0000-4000-8000-000000000001'),2,'retry creates no duplicate learner/tutor message');
set local role authenticated;
set local request.jwt.claim.sub='d0000000-0000-4000-8000-000000000001';
select is((select count(*)::int from activities),0,'RLS hides another learner activities');
select throws_ok($$select learning_snapshot('c0000000-0000-4000-8000-000000000001')$$,'42501',null,'browser cannot read authoritative snapshot');
select throws_ok($$select start_learning('c0000000-0000-4000-8000-000000000001')$$,'42501',null,'browser cannot invoke session authority');
select throws_ok($$update profiles set learning_revision=999$$,'42501',null,'browser cannot forge optimistic revision');
select throws_ok($$insert into teaching_decisions(user_id,session_id,learning_objective,purpose,selected_method,difficulty_level,english_exposure_level,native_support_level,correction_strategy,reason_category,evidence_basis) values(auth.uid(),gen_random_uuid(),'fake','communication','fake',1,1,1,'fake','fake','fake')$$,'42501',null,'browser cannot forge teaching decision');
select throws_ok($$insert into evidence_events(user_id,source,evidence_kind,result,dedupe_key) values(auth.uid(),'deterministic','fake','success','fake-evidence-key-123')$$,'42501',null,'browser cannot forge evidence');
reset role;
insert into evidence_events(id,user_id,source,evidence_kind,result,dedupe_key) values('d3000000-0000-4000-8000-000000000001','d0000000-0000-4000-8000-000000000001','system','ownership_test','neutral','ownership-test-event-key');
select throws_ok($$insert into learner_model_change_evidence(user_id,learner_model_change_id,evidence_event_id) select 'd0000000-0000-4000-8000-000000000001',id,'d3000000-0000-4000-8000-000000000001' from learner_model_changes where user_id='c0000000-0000-4000-8000-000000000001'$$,'23503',null,'composite ownership protects audit links');
select is(plan_learning('c0000000-0000-4000-8000-000000000001',(select sid from learning_ids),0,'{}','{}'),null::uuid,'stale teaching plan does not write');
alter table learning_ids add column next_aid uuid;
update learning_ids set next_aid=plan_learning('c0000000-0000-4000-8000-000000000001',sid,3,(select metadata->'decision' from activities where id=aid),(select metadata->'task' from activities where id=aid));
select ok((select next_aid is not null from learning_ids),'next activity persists after completed response');
select control_learning('c0000000-0000-4000-8000-000000000001',(select next_aid from learning_ids),'support','replay');
select is((select (metadata->>'support')::int from activities where id=(select next_aid from learning_ids)),0,'first listen is independent');
select control_learning('c0000000-0000-4000-8000-000000000001',(select next_aid from learning_ids),'support','replay');
select is((select (metadata->>'support')::int from activities where id=(select next_aid from learning_ids)),1,'repeated listening records support');
select control_learning('c0000000-0000-4000-8000-000000000001',(select next_aid from learning_ids),'support','next');
select is((select (metadata->>'support')::int from activities where id=(select next_aid from learning_ids)),2,'hint ladder increments durably');
select control_learning('c0000000-0000-4000-8000-000000000001',(select next_aid from learning_ids),'feedback','tired');
select is((select state_type from session_states where user_id='c0000000-0000-4000-8000-000000000001' and ended_at is null),'tired','explicit tiredness affects current session');
select is((select estimate_level::int from learner_ability_estimates where user_id='c0000000-0000-4000-8000-000000000001'),0,'session tiredness does not change ability');
select is((select count(*)::int from learner_model_change_evidence e join learner_model_changes c on c.id=e.learner_model_change_id where c.changed_entity_type='session_state'),1,'session state change links neutral feedback evidence');
select control_learning('c0000000-0000-4000-8000-000000000001',(select next_aid from learning_ids),'feedback','tired');
select is((select count(*)::int from user_feedback where user_id='c0000000-0000-4000-8000-000000000001'),1,'feedback retry is idempotent');
select end_learning('c0000000-0000-4000-8000-000000000001',(select sid from learning_ids));
select is((select count(*)::int from session_states where user_id='c0000000-0000-4000-8000-000000000001' and ended_at is null),0,'ending session closes temporary states');
select start_learning('c0000000-0000-4000-8000-000000000001');
select is((select state_type from session_states where user_id='c0000000-0000-4000-8000-000000000001' and ended_at is null),'normal','new session does not inherit tiredness');
select * from finish();
rollback;
